import unittest
from candidate import vowels_count

class TestVowelsCount(unittest.TestCase):
    def test_vowels_count_normalcase(self):
        self.assertEqual(vowels_count("abcde"), 2)

    def test_vowels_count_uppercase(self):
        self.assertEqual(vowels_count("ACEDY"), 3)

    def test_vowels_count_single_vowel(self):
        self.assertEqual(vowels_count("a"), 1)

    def test_vowels_count_empty_string(self):
        self.assertEqual(vowels_count(""), 0)

    def test_vowels_count_only_y(self):
        self.assertEqual(vowels_count("y"), 1)

    def test_vowels_count_no_vowels(self):
        self.assertEqual(vowels_count("xyz"), 0)

    def test_vowels_count_vowel_at_beginning(self):
        self.assertEqual(vowels_count("aeu"), 3)

    def test_vowels_count_y_at_end(self):
        self.assertEqual(vowels_count("acedy"), 3)

    def test_vowels_count_y_at_beginning(self):
        self.assertEqual(vowels_count("yaeu"), 3)

    def test_vowels_count_y_at_middle(self):
        self.assertEqual(vowels_count("acedyz"), 3)

if __name__ == '__main__':
    unittest.main()
